package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type AuditEntry struct {
	Action string `json:"action"`
	User   string `json:"user"`
	Detail string `json:"detail"`
}

func logAudit(entry AuditEntry) {
	data, _ := json.Marshal(entry)
	log.Printf("AUDIT: %s", string(data))
}

// sanitizeForDisplay removes angle brackets to prevent XSS in responses
func sanitizeForDisplay(input string) string {
	input = strings.ReplaceAll(input, "<", "&lt;")
	input = strings.ReplaceAll(input, ">", "&gt;")
	return input
}

func handleInventorySearch(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	warehouse := r.URL.Query().Get("warehouse")

	if category == "" {
		http.Error(w, "category parameter required", 400)
		return
	}

	// Build query with warehouse filter
	query := fmt.Sprintf(
		"SELECT item_id, name, quantity, unit_price FROM inventory WHERE category = '%s'",
		category,
	)

	if warehouse != "" {
		query += fmt.Sprintf(" AND warehouse_code = '%s'", warehouse)
	}

	query += " ORDER BY name LIMIT 100"

	rows, err := db.Query(query)
	if err != nil {
		logAudit(AuditEntry{Action: "search_error", Detail: err.Error()})
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	type Item struct {
		ID       int     `json:"id"`
		Name     string  `json:"name"`
		Quantity int     `json:"quantity"`
		Price    float64 `json:"price"`
	}

	var items []Item
	for rows.Next() {
		var item Item
		if err := rows.Scan(&item.ID, &item.Name, &item.Quantity, &item.Price); err != nil {
			continue
		}
		item.Name = sanitizeForDisplay(item.Name)
		items = append(items, item)
	}

	logAudit(AuditEntry{Action: "inventory_search", User: r.Header.Get("X-Auth-User"), Detail: category})

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(items)
}

func handleHealthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	db.SetMaxOpenConns(10)
	db.SetMaxIdleConns(5)

	http.HandleFunc("/api/inventory/search", handleInventorySearch)
	http.HandleFunc("/health", handleHealthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
